using System.Collections.Generic;
using UnityEngine;

namespace Pitt.OnePit
{
    /// v6m W (п. 118, Максим 04.11: «на полу одновременно только 1–2 ближайших по очереди кружка покупки»; эталоны этапов 1–2: на полу один-два круга).
    /// Очередь кружков зоны 1 (ряд сборщиков, лента, пушка, улучшатели, мотор): кружок, который HallProduction открыл (Show(true)), встаёт в очередь
    /// в порядке появления. На полу виден не больше Cap кружков; остальные придержаны — для мира скрыты (не в BuyCircle.All, оплату не берут,
    /// на экране нет), но остаются в очереди и появляются, как только место освободилось. Выбор — по приоритету:
    ///   1) уже частично оплаченный (игрок вложился — не прятать),
    ///   2) главная цель маяка (GoalBeacon) или кружок, снимающий нужду (HallNeeds.Want),
    ///   3) открытый раньше закрытого замком уровня Ямы,
    ///   4) уже видимый раньше новичка (без мигания), затем порядок появления.
    /// Не трогает: кружки класса Б (только лист «Прокачки»), зоны 2+ (Спортзал, Пресс-цех: у них свой порядок шагов), темп открытий
    /// HallProduction (PaceGoals) — придержанный кружок остаётся целью, новые открываются по-старому, поэтому экономика и темп те же.
    /// QA: `-pittOpFloorCap N` — N кружков (по умолчанию 2); 0 — без ограничения (как v6l). Лог: `floor focus hold id= shown=`, `floor focus show id=`.
    public sealed class FloorFocus : MonoBehaviour
    {
        public const int CapDefault = 2;
        static int _cap = -1;
        /// Сколько кружков показывать на полу (0 — без предела).
        public static int Cap
        {
            get { if (_cap < 0) _cap = Args.Has("-pittOpFloorCap") ? Mathf.Max(0, Args.GetI("-pittOpFloorCap", CapDefault)) : CapDefault; return _cap; }
            set { _cap = Mathf.Max(0, value); }
        }

        static readonly List<BuyCircle> _q = new List<BuyCircle>(16);
        static FloorFocus _i;
        /// Сколько кружков придержано сейчас и всего придержек за игру (тесты, KPI).
        public static int HeldNow { get; private set; }
        public static int Holds;
        /// Наибольшее число кружков зоны 1 на полу разом (KPI): должно быть ≤ Cap.
        public static int MaxShown;

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        public static void Reset() { _q.Clear(); _i = null; _cap = -1; HeldNow = 0; Holds = 0; MaxShown = 0; }

        /// Кружок класса А в зоне 1, в очереди на пол.
        static bool Subject(BuyCircle c) => c && !c.SheetOnly && c.Zone == HallProdDefs.Zone && !c.Done;

        internal static void Remember(BuyCircle c)
        {
            if (!c || !OnePitBalance.FlowV3 || c.Zone != HallProdDefs.Zone) return;
            if (!_q.Contains(c)) _q.Add(c);
            if (!_i && !Game.IsSim && c.transform.parent)
            {
                var go = new GameObject("FloorFocus");
                go.transform.SetParent(c.transform.parent, false);
                _i = go.AddComponent<FloorFocus>();
            }
            // в sim (бот, ферма) компонента нет — решение принимаем сразу и на каждом кадре через Step из HallProduction-независимого хука ниже
            if (Game.IsSim || !_i) Step();
        }

        internal static void Forget(BuyCircle c)
        {
            if (_q.Remove(c) && Cap > 0) { /* освободившееся место займёт следующий — на ближайшем Step */ }
        }

        void Update() => Step();

        /// Кадр: оставить на полу первых Cap по приоритету, остальных придержать. Дёшево: в очереди единицы кружков.
        public static void Step()
        {
            int cap = Cap;
            for (int i = _q.Count - 1; i >= 0; i--) if (!Subject(_q[i]) || !_q[i].Wanted) _q.RemoveAt(i);
            if (_q.Count == 0) { HeldNow = 0; return; }
            if (cap <= 0 || !OnePitBalance.FlowV3)
            {
                for (int i = 0; i < _q.Count; i++) _q[i].SetHeld(false);
                HeldNow = 0;
                return;
            }
            // порядок: приоритет, затем «уже виден», затем порядок появления (вставкой — очередь мала)
            _sorted.Clear();
            for (int i = 0; i < _q.Count; i++)
            {
                var c = _q[i];
                int k = 0;
                while (k < _sorted.Count && Before(_sorted[k], c)) k++;
                _sorted.Insert(k, c);
            }
            int shown = 0, held = 0;
            for (int i = 0; i < _sorted.Count; i++)
            {
                var c = _sorted[i];
                bool hold = i >= cap;
                if (hold != c.Held)
                {
                    c.SetHeld(hold);
                    if (hold) Holds++;
                    Debug.Log(System.FormattableString.Invariant($"[PITT] [onepit] floor focus {(hold ? "hold" : "show")} id={c.Id} queue={_sorted.Count} cap={cap} t={OnePitState.HallTime:0.0}"));…

