#!/usr/bin/env python3
# v6m M: подготовка иконок kit-v6m для Unity: уменьшить, убрать шум у кромки (порог альфы + мелкие компоненты),
# довести альфу внутри силуэта до 255. Запуск: .cache/venv-pil/bin/python3 prep_icons.py <src> <dst>
import sys, os
from PIL import Image
from collections import deque

BIG = {"piggy_duck": 512, "vip_chest": 512}
DEFAULT = 256
THR = 40           # альфа ниже порога -> 0
MIN_FRAC = 0.002   # компонента меньше этой доли холста -> удалить

def premul_resize(im, size):
    r, g, b, a = im.split()
    # premultiply
    px = im.load()
    w, h = im.size
    pm = Image.new("RGBA", im.size)
    pp = pm.load()
    for y in range(h):
        for x in range(w):
            R, G, B, A = px[x, y]
            pp[x, y] = (R * A // 255, G * A // 255, B * A // 255, A)
    pm = pm.resize((size, size), Image.LANCZOS)
    out = Image.new("RGBA", pm.size)
    po, pq = out.load(), pm.load()
    for y in range(size):
        for x in range(size):
            R, G, B, A = pq[x, y]
            if A == 0:
                po[x, y] = (0, 0, 0, 0)
            else:
                po[x, y] = (min(255, R * 255 // A), min(255, G * 255 // A), min(255, B * 255 // A), A)
    return out

def clean(im):
    w, h = im.size
    px = im.load()
    for y in range(h):
        for x in range(w):
            if px[x, y][3] < THR:
                px[x, y] = (0, 0, 0, 0)
    # компоненты по alpha>0 (8-связность)
    seen = bytearray(w * h)
    comps = []
    for y in range(h):
        for x in range(w):
            i = y * w + x
            if seen[i] or px[x, y][3] == 0:
                continue
            q = deque([(x, y)]); seen[i] = 1; cells = []
            while q:
                cx, cy = q.popleft(); cells.append((cx, cy))
                for dx in (-1, 0, 1):
                    for dy in (-1, 0, 1):
                        nx, ny = cx + dx, cy + dy
                        if 0 <= nx < w and 0 <= ny < h:
                            j = ny * w + nx
                            if not seen[j] and px[nx, ny][3] > 0:
                                seen[j] = 1; q.append((nx, ny))
            comps.append(cells)
    comps.sort(key​=[скрыто], reverse=True)
    keep = len(comps[0]) if comps else 0
    removed = 0
    for cells in comps[1:]:
        if len(cells) < MIN_FRAC * w * h:
            for (cx, cy) in cells:
                px[cx, cy] = (0, 0, 0, 0)
            removed += 1
    # внутренность: пиксели, до которых нельзя дойти от края по alpha<128
    outside = bytearray(w * h)
    q = deque()
    for x in range(w):
        for y in (0, h - 1):
            if px[x, y][3] < 128 and not outside[y * w + x]:
                outside[y * w + x] = 1; q.append((x, y))
    for y in range(h):
        for x in (0, w - 1):
            if px[x, y][3] < 128 and not outside[y * w + x]:
                outside[y * w + x] = 1; q.append((x, y))
    while q:
        cx, cy = q.popleft()
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nx, ny = cx + dx, cy + dy
            if 0 <= nx < w and 0 <= ny < h and not outside[ny * w + nx] and px[nx, ny][3] < 128:
                outside[ny * w + nx] = 1; q.append((nx, ny))
    filled = 0
    for y in range(h):
        for x in range(w):
            r, g, b, a = px[x, y]
            if not outside[y * w + x] and a >= 128 and a < 255:
                # внутри силуэта (alpha>=128) — довести до 255; цвет без полупрозрачных «дыр» берём как есть
                px[x, y] = (r, g, b, 255); filled += 1
            elif not outside[y * w + x] and a < 128:
                # дырка внутри силуэта (недостающий пиксель): закрасить цветом ближайшего соседа
                pass
    return removed, filled

def main(src, dst):
    os.makedirs(dst, exist_ok=True)
    names = [f for f in sorted(os.listdir(src)) if f.endswith(".png")]
    for f in names:
        base = f[:-4]
        if base == "key​":  # key.png с серым квадратом — только key_v2​
            continue
        im = Image.open(os.path.join(src, f)).convert("RGBA")
        # квадрат: speaker 1265x1243 — вписать в квадрат
        if im.size[0] != im.size[1]:
            s = max(im.size); sq = Image.new("RGBA", (s, s), (0, 0, 0, 0))
            sq.paste(im, ((s - im.size[0]) // 2, (s - im.size[1]) // 2)); im = sq
        name = "key​" if base == "key_v2​" else base
        size = BIG.get(name, DEFAULT)
        sm = premul_resize(im, size)
        removed, filled = clean(sm)
        sm.save(os.path.join(dst, name + ".png"), optimize=True)
        print(f"{name:12s} {size} removed_comps={removed} filled={filled}")

if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
